    88      if (!fo) {
    89          return 0;
    90      }
    91      unsigned disp;
    92      unsigned len = sz_pack2a;  // after headers and all PT_LOAD
    93
    94      unsigned const t = (4 & len) ^ ((!!xct_off)<<2);  // 0 or 4
    95      if (t) {
    96          if (fo) {
    97              unsigned const zero = 0;
    98              fo->write(&zero, t);
    99          }
   100          len += t;  // force sz_pack2 (0 mod 8)  [see below]
   101      }
